package kz.quizgenerator
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import kotlinx.coroutines.runBlocking
import org.json.JSONObject
import org.json.JSONArray
import java.io.File
import java.util.UUID
class BatchJobsTest {
 @get:Rule val folder=TemporaryFolder()
 private val set=UUID.randomUUID().toString()
 private fun plan(count: Int=200)=BatchPlanning.quiz("alice",set,"Физика",AiInputMode.TOPIC,"Законы Ньютона","НЕ ОТПРАВЛЯТЬ",count,"medium").accepted(1)
 private fun reply(count: Int,offset: Int=0): JSONObject=JSONObject(QuizJson.serialize(Quiz(UUID.randomUUID().toString(),"Тест",List(count){QuizQuestion("q$it","Вопрос "+(it+offset),listOf("А","Б"),0,explanation="Объяснение")},generatedByAi=true)))
 @Test fun twoHundredAndTwoHundredThreeAreQuestionPlansNotSourceParts() {assertEquals(List(8){25},plan().parts.map {it.expected});assertEquals(List(8){25}+3,plan(203).parts.map {it.expected});assertTrue(plan().parts.all {JSONObject(it.payload).getString("material").isEmpty()})}
 @Test fun allSingleRequestLimitsHoldAndIdsAreStable() {for(n in listOf(1,25,100,200,203,500)){val p=plan(n);assertEquals(n,p.parts.sumOf {it.expected});assertTrue(p.parts.all {it.expected in 1..25});assertEquals(p.parts.size,p.parts.map {it.requestId}.toSet().size);p.parts.forEach {AiRequestRules.validate(it.route,JSONObject(it.payload))}}}
 @Test fun documentCoverageIsExactAndIndependentFromQuestionCount() {val text=(1..800).joinToString(" "){"Предложение $it объясняет физику и движение материальных тел."};val chunks=BatchPlanning.chunks(text,8);assertEquals(text,chunks.joinToString(""));assertTrue(chunks.all {it.length<=9800});val p=BatchPlanning.quiz("alice",set,"Курс",AiInputMode.DOCUMENT,"Физика",text,200,"medium");assertEquals(200,p.parts.sumOf {it.expected});assertEquals(chunks.size,p.parts.size);assertEquals(chunks.size,chunks.toSet().size)}
 @Test fun shortSourceIsNotRepeatedEightTimesAndLargeSentenceIsNotCut() {assertThrows(IllegalArgumentException::class.java){BatchPlanning.quiz("alice",set,"Курс",AiInputMode.TEXT,"","Короткое предложение.",200,"medium")};assertThrows(IllegalArgumentException::class.java){BatchPlanning.chunks("x".repeat(10000),1)}}
 @Test fun atomicStoreSurvivesRestartAndRejectsCrossAccountAndChangedPurpose() {val store=BatchJobStore(folder.root,"alice");val p=plan();store.save(p);assertEquals(p,BatchJobStore(folder.root,"alice").load(p.id));assertThrows(IllegalArgumentException::class.java){BatchJobStore(folder.root,"bob").load(p.id)};val before=File(folder.root,"batch_jobs/${p.id}.json").readBytes();assertThrows(IllegalArgumentException::class.java){store.save(p.copy(target=203))};assertArrayEquals(before,File(folder.root,"batch_jobs/${p.id}.json").readBytes())}
 @Test fun sequentialGenerationRestartsWithoutRepeatingDonePartsAndProducesOneQuiz()=runBlocking {val store=BatchJobStore(folder.root,"alice");var now=100000L;var calls=0;val p=plan();store.save(p);var j=p;repeat(3){j=BatchEngine(store){now}.step(p.id){_,body,_->val result=reply(body.getInt("count"),calls*25);calls++;result};now+=22000};assertEquals(75,j.actual);val reloaded=BatchJobStore(folder.root,"alice");repeat(5){j=BatchEngine(reloaded){now}.step(p.id){_,body,_->val result=reply(body.getInt("count"),calls*25);calls++;result};now+=22000};assertEquals(8,calls);assertEquals(BatchStatus.COMPLETE,j.status);assertEquals(200,j.quiz().questions.size);assertEquals(p.id,j.quiz().id);assertTrue(j.quiz().questions.all {it.evidence==AnswerEvidence.CLOUD_AI})}
 @Test fun minutePacingAndRepeatDeliveryCannotSendEarlyOrTwice()=runBlocking {val store=BatchJobStore(folder.root,"alice");val p=plan(26);store.save(p);var calls=0;val engine=BatchEngine(store){100000};engine.step(p.id){_,body,_->calls++;reply(body.getInt("count"))};engine.step(p.id){_,_,_->calls++;reply(1)};assertEquals(1,calls);assertEquals(1,store.load(p.id).done)}
 @Test fun incompletePartPersistsActualCountAndStopsRatherThanClaimingCompletion()=runBlocking {val store=BatchJobStore(folder.root,"alice");val p=plan(25);store.save(p);val j=BatchEngine(store){100000}.step(p.id){_,_,_->reply(20)};assertEquals(20,j.actual);assertEquals(0,j.done);assertEquals(BatchStatus.REVIEW,j.status);assertEquals(20,j.quiz().questions.size)}
 @Test fun obviousDuplicateStopsAndKeepsEarlierResults()=runBlocking {val store=BatchJobStore(folder.root,"alice");val p=plan(26);store.save(p);BatchEngine(store){100000}.step(p.id){_,_,_->reply(25)};val j=BatchEngine(store){122000}.step(p.id){_,_,_->reply(1)};assertEquals(25,j.actual);assertNotEquals(BatchStatus.COMPLETE,j.status)}
 @Test fun quotaStopsAndResumeKeepsSameRequestIdAndCompletedResults()=runBlocking {val store=BatchJobStore(folder.root,"alice");val p=plan(26);store.save(p);val id=p.parts[0].requestId;var calls=0;val engine=BatchEngine(store){100000};val j=engine.step(p.id){_,_,_->calls++;throw AiServerFailure(429,"quota")};assertEquals(BatchStatus.LIMIT,j.status);assertEquals(id,j.parts[0].requestId);engine.step(p.id){_,_,_->calls++;reply(1)};assertEquals(1,calls);assertEquals(BatchStatus.READY,engine.resume(p.id).status)}
 @Test fun lostResponse409And503NeverLoopOrReplaceIdWithoutExplicitRetry()=runBlocking {for(code in listOf(0,409,502,503)){val sub=folder.newFolder("case$code");val store=BatchJobStore(sub,"alice");val p=plan(1);store.save(p);var calls=0;val engine=BatchEngine(store){100000};val j=engine.step(p.id){_,_,_->calls++;if(code==0)throw java.io.IOException("lost") else throw AiServerFailure(code,"server")};assertEquals(BatchStatus.UNCERTAIN,j.status);engine.step(p.id){_,_,_->calls++;reply(1)};assertEquals(1,calls);assertEquals(p.parts[0].requestId,j.parts[0].requestId);val retry=engine.retryUnknown(p.id);assertNotEquals(p.parts[0].requestId,retry.parts[0].requestId)}}
 @Test fun cancelAndInterruptedSnapshotNeverAutoResume()=runBlocking {val store=BatchJobStore(folder.root,"alice");val p=plan(1);store.save(p);val e=BatchEngine(store){100000};e.pause(p.id,true);var calls=0;e.step(p.id){_,_,_->calls++;reply(1)};assertEquals(0,calls);val crash=p.copy(status=BatchStatus.RUNNING,parts=p.parts.map {it.copy(status=BatchPartStatus.SENDING)});store.save(crash);val restored=store.restore(store.load(p.id));assertEquals(BatchStatus.UNCERTAIN,restored.status);assertEquals(BatchPartStatus.UNKNOWN,restored.parts[0].status)}
 @Test fun answerPlanShrinksBatchesToByteAndContextLimitsAndExcludesConfirmedKeys() {val q=QuizQuestion("known","Известный?",listOf("Да","Нет"),0,null);val bank=Quiz(UUID.randomUUID().toString(),"Банк",listOf(q)+(1..200).map {QuizQuestion("q$it","Вопрос $it?",listOf("А","Б"),null,null)});val p=BatchPlanning.answers("alice",set,bank);assertEquals(200,p.target);assertEquals(8,p.parts.size);assertFalse(p.parts.any {it.payload.contains("known")});val big=bank.copy(questions=bank.questions.drop(1).take(10).map {it.copy(text=it.text+"я".repeat(3000))});val smaller=BatchPlanning.answers("alice",set,big);assertTrue(smaller.parts.all {it.expected<=3})}
 @Test fun mismatchedIdsAndUncertainAnswersAreValidatedWithoutOverwritingSourceOrText() {val q=QuizQuestion("q","Чётные?",listOf("2","3","4"),null,null);val bank=Quiz(UUID.randomUUID().toString(),"Банк",listOf(q));val p=BatchPlanning.answers("alice",set,bank).accepted(1);val response=JSONObject().put("answers",JSONArray().put(JSONObject().put("id","q").put("indices",JSONArray(listOf(0,2))).put("uncertain",true).put("explanation","Проверить")));val j=p.copy(parts=p.parts.map {it.copy(status=BatchPartStatus.DONE,response=response.toString())});val changed=BatchAnswerMerge.apply(j,bank);assertEquals(q.text,changed.questions[0].text);assertEquals(q.options,changed.questions[0].options);assertEquals(setOf(0,2),changed.questions[0].correctIndices.toSet());assertEquals(AnswerEvidence.CLOUD_AI,changed.questions[0].evidence);assertFalse(changed.questions[0].evidence.confirmed);val manual=bank.copy(questions=listOf(q.copy(correctIndex=1,evidence=AnswerEvidence.MANUAL)));assertEquals(manual,BatchAnswerMerge.apply(j,manual));assertEquals(AnswerEvidence.MANUAL,BatchAnswerMerge.apply(j,changed,"q",setOf(0,2)).questions[0].evidence);response.getJSONArray("answers").getJSONObject(0).put("id","foreign");assertThrows(IllegalArgumentException::class.java){StudyContract.answers(response,JSONObject(p.parts[0].payload))}}
 @Test fun lectureStoreFormattingEditsRestartIsolationAndDeletionAreLocal() {val a=folder.newFolder("alice");val b=folder.newFolder("bob");val v=Lecture(UUID.randomUUID().toString(),set,"Физика","## Раздел\nF = m·a\n- Термин",null,null,false);LectureStore(a).save(v);assertEquals(v,LectureStore(a).load(v.id));val edited=v.copy(title="Механика",body=v.body+"\nПояснение",edited=true,complete=true);LectureStore(a).save(edited);assertEquals(edited,LectureStore(a).list(set).single());assertThrows(IllegalArgumentException::class.java){LectureStore(b).load(v.id)};LectureStore(a).delete(v.id);assertTrue(LectureStore(a).list(set).isEmpty())}
}
